function M.instances()
  return vim.list_slice(instances, 1, #instances)
end

function M.load(namespace, opts)
  if type(namespace) ~= "string" or namespace == "" then
    return nil
  end
  return store.load_readonly(namespace, opts or { dir = DEFAULT_CACHE_DIR })
end

function M.list_snapshots(namespace, opts)
  if type(namespace) ~= "string" or namespace == "" then
    return {}
  end
  local inst = M.get(namespace)
  return store.list_snapshots(
    namespace,
    opts or (inst and inst._cache_opts) or { dir = DEFAULT_CACHE_DIR }
  )
end

function M.load_snapshot(namespace, name, opts)
  if type(namespace) ~= "string" or namespace == "" or type(name) ~= "string" or name == "" then
    return nil
  end
  local inst = M.get(namespace)
  return store.load_snapshot(
    namespace,
    name,
    opts or (inst and inst._cache_opts) or { dir = DEFAULT_CACHE_DIR }
  )
end

function M.markdown_all(opts)
  return report_mod.markdown_all(M.report_all(opts))
end

function M.is_disabled(namespace)
  local inst = M.get(namespace)
  return toggle.is_disabled(namespace, inst and inst._cache_opts or nil)
end

function M.disabled()
  return toggle.disabled_list()
end

function M.available()
  return pcall(require, "mdview")
end

local function telemetry()
  return require("runtime-analysis.telemetry")
end

function M.setup(opts)
  opts = opts or {}
  if opts.report_style ~= nil then
    G.report_style = opts.report_style
  end
end

function M.report_style()
  return G.report_style
end

local function root_of(modname)
  return (modname:match("^([^.]+)") or modname)
end

function M.configured()
  return configured
end

function M.info(container, field)
  local by_field = sites[container]
  local site = by_field and by_field[field]
  if not site or container[field] ~= site.wrapper then
    return { wrapped = false, namespaces = {} }
  end
  local namespaces = {}
  for i = 1, #site.subs do
    namespaces[#namespaces + 1] = site.subs[i].inst.namespace
  end
  table.sort(namespaces)
  return { wrapped = true, namespaces = namespaces }
end

local function days_collected(data)
  return math.floor((os.time() - (data.started_at or os.time())) / 86400)
end

function M.namespace_path(namespace, opts)
  return M.dir(opts) .. "/" .. store.sanitize(namespace) .. ".md"
end

function M.namespace_html_path(namespace, opts)
  return M.dir(opts) .. "/" .. store.sanitize(namespace) .. ".html"
end

function M.combined_path(opts)
  return M.dir(opts) .. "/report.md"
end

function M.combined_html_path(opts)
  return M.dir(opts) .. "/report.html"
end

function M.is_running()
  return running
end

function M.reset()
  entries = {}
  by_name = {}
  stack = {}
end

local function root_of(modname)
  return (modname:match("^([^.]+)") or modname)
end

function M.cache_key(namespace)
  return "telemetry/" .. M.sanitize(namespace)
end

function M.today()
  return os.date("%Y-%m-%d") --[[@as string]]
end

local function normalize(raw)
  if type(raw) ~= "table" or raw.version ~= M.VERSION then
    return M.empty()
  end
  raw.functions = type(raw.functions) == "table" and raw.functions or {}
  raw.days = type(raw.days) == "table" and raw.days or {}
  raw.reminded = type(raw.reminded) == "table" and raw.reminded or {}
  raw.sessions = tonumber(raw.sessions) or 0
  raw.started_at = tonumber(raw.started_at) or os.time()
  -- Added after version 1 shipped; older cache files simply lack it. Purely
  -- additive, so this does not warrant a version bump — a missing map and an
  -- empty one mean the same thing to every reader.
  raw.modules = type(raw.modules) == "table" and raw.modules or {}
  raw.info = type(raw.info) == "table" and raw.info or {}
  return raw
end

function M.load(namespace, opts)
  local ok, raw = pcall(disk.load, M.cache_key(namespace), opts)
  return normalize(ok and raw or nil)
end

function M.snapshot_cache_key(namespace, name)
  return M.cache_key(namespace) .. "/snapshots/" .. M.sanitize_snapshot_name(name)
end

function M.is_disabled(namespace, opts)
  return load(opts)[namespace] == true
end

local function join_continuations(cmd)
  return (cmd:gsub("\\[ \t]*\r?\n", " "))
end

local function resolve_root(opts)
  return (opts and opts.root) or default_root()
end

function M.current()
  return current_name
end

local function substitute(str, vars)
  return (str:gsub("{{%s*([%w_.%-]+)%s*}}", function(name)
    return tostring(vars[name])
  end))
end

local function cache_key(root)
  return "history/" .. sanitize(project_key(root))
end

function M.list(opts)
  opts = opts or {}
  local entries = disk.load(cache_key(opts.root), opts) or {}
  local out = {}
  for i = #entries, 1, -1 do
    out[#out + 1] = entries[i]
  end
  return out
end

function M.clear(opts)
  opts = opts or {}
  return disk.clear(cache_key(opts.root), opts)
end

function M.is_loaded(module_id)
  return type(module_id) == "string" and package.loaded[module_id] ~= nil
end

local function cache_key(prefix)
  return "loaded/" .. sanitize(prefix)
end

local function snapshot_cache_key(prefix, name)
  return cache_key(prefix) .. "/snapshots/" .. sanitize(name)
end

local function extract_boundary(content_type)
  return content_type:match('boundary="([^"]+)"') or content_type:match("boundary=([^;%s]+)")
end

local function body_lines(body)
  return vim.split(body, "\n", { plain = true })
end

local function command_name(line)
  return line:match("^%s*[%d,.$'<>%+%-]*%s*(%a[%w_]*)")
end

function M.is_running()
  return inst ~= nil
end

function M.report(report_opts)
  return inst and inst.report(report_opts)
end

function M.lines(report_opts)
  if not inst then
    return { "runtime-analysis.usage is not running — call M.start() first" }
  end
  return inst.lines(report_opts)
end

function M.markdown(report_opts)
  if not inst then
    return { "_(runtime-analysis.usage is not running)_" }
  end
  return inst.markdown(report_opts)
end
